export class ManufacturerComponent implements OnInit {
  private http = inject(HttpClient); private msgs = inject(MessagesService);
  list: ManufacturerDto[] = [];
  editing: ManufacturerDto | null = null; name = '';
  ngOnInit() { this.load(); }
  load() {
    this.http.get<ManufacturerDto[]>(API + '/manufacturers').subscribe({
      next: l => this.list = l, error: () => this.msgs.error('An error occurred while loading manufacturers') });
  }
  open(m: ManufacturerDto) { this.editing = m; this.name = m.name ?? ''; }
  save() {
    const dto = { ...this.editing, name: this.name };
    this.http.post<ManufacturerDto>(API + '/manufacturers', dto).subscribe({
      next: saved => {
        this.editing = null;
        this.msgs.success('Manufacturer saved');
        const i = this.list.findIndex(x => x.id === saved.id);
        if (i >= 0) { const l = [...this.list]; l[i] = saved; this.list = l; } else this.list = [...this.list, saved];
      },
      error: () => this.msgs.error('An error occurred while saving the manufacturer'),
    });
  }
  remove(m: ManufacturerDto) {
    if (!window.confirm('Are you sure you want to delete ' + m.name + '?')) return;
    this.http.delete(API + '/manufacturers/' + m.id).subscribe({
      next: () => { this.list = this.list.filter(x => x !== m); this.msgs.success('Manufacturer deleted'); },
      error: () => this.msgs.error('An error occurred while deleting the manufacturer'),
    });
  }
}
