.message{padding:8px;margin:4px}.message.success{background:#dfd}.message.error{background:#fdd}.close{cursor:pointer;margin-left:12px}
.overlay{position:fixed;inset:0;background:rgba(0,0,0,.3)}.popup{position:fixed;top:100px;left:50%;transform:translateX(-50%);background:#fff;padding:16px;border:1px solid #888}
.popup label{display:block;margin:6px 0}
EOF
