const WebSocket=require('/work/node_modules/ws');const http=require('http');
const {spawn}=require('child_process');
const ch=spawn(process.env.CHROME_BIN,['--headless','--no-sandbox','--disable-gpu','--remote-debugging-port=9333','about:blank']);
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const get=u=>new Promise(r=>http.get(u,res=>{let d='';res.on('data',c=>d+=c);res.on('end',()=>r(JSON.parse(d)))}));
(async()=>{await sleep(2000);const t=(await get('http://127.0.0.1:9333/json')).find(x=>x.type==='page');
const ws=new WebSocket(t.webSocketDebuggerUrl);await new Promise(r=>ws.on('open',r));let id=0;const p={};
ws.on('message',m=>{m=JSON.parse(m);if(p[m.id]){p[m.id](m.result);delete p[m.id]}});
const send=(method,params)=>new Promise(r=>{p[++id]=r;ws.send(JSON.stringify({id,method,params}))});
const ev=async e=>(await send('Runtime.evaluate',{expression:e,awaitPromise:true,returnByValue:true})).result.value;
const ok=(n,c)=>{console.log((c?'PASS ':'FAIL ')+n);if(!c)process.exitCode=1};
const rows=id=>ev(`document.querySelectorAll('#${id} tbody')[0].rows.length`);
const go=async h=>{await send('Page.navigate',{url:'http://localhost:8888/ng/#'+h});await sleep(2500)};
const typ=async(sel,v)=>ev(`(()=>{const e=document.querySelector('${sel}');e.value='${v}';e.dispatchEvent(new Event('input'));})()`);
const click=s=>ev(`document.querySelector('${s}').click()`);
await go('manufacturer');
// navigation via menubar
await ev(`[...document.querySelectorAll('#gwt-debug-menubar a')].find(a=>a.href.includes('rating')).click()`);await sleep(1500);
ok('menubar->rating',await ev('location.href.includes("#/rating")'));
await ev(`[...document.querySelectorAll('#gwt-debug-menubar a')].find(a=>a.href.includes('manufacturer')).click()`);await sleep(1500);
let n=await rows('gwt-debug-manufacturers');
await click('#gwt-debug-create-manufacturer');await sleep(500);
ok('editor visible',await ev('!!document.querySelector("#gwt-debug-manufacturer-editor")'));
await typ('#gwt-debug-manufacturer-input','Ford');await click('#gwt-debug-manufacturer-close');await sleep(500);
ok('close unchanged',await rows('gwt-debug-manufacturers')===n);
await click('#gwt-debug-create-manufacturer');await sleep(300);await typ('#gwt-debug-manufacturer-input','Plymouth');await click('#gwt-debug-manufacturer-save');await sleep(1500);
ok('saved msg',await ev(`(document.querySelector('#gwt-debug-successMessage span')||{}).textContent?.includes('saved')`));
ok('incremented',await rows('gwt-debug-manufacturers')>n);
ok('last Plymouth',await ev(`[...document.querySelector('#gwt-debug-manufacturers tbody').rows].at(-1).cells[1].textContent==='Plymouth'`));
await click('#gwt-debug-successMessage span:last-child');await sleep(300);
ok('msg closed',await ev('!document.querySelector("#gwt-debug-successMessage")'));
await click('#gwt-debug-manufacturers tbody td:nth-last-child(2) button');await sleep(300);
await typ('#gwt-debug-manufacturer-input','Ford');await click('#gwt-debug-manufacturer-save');await sleep(1500);
ok('first Ford',await ev(`document.querySelector('#gwt-debug-manufacturers tbody').rows[0].cells[1].textContent==='Ford'`));
n=await rows('gwt-debug-manufacturers');await ev('window.confirm=()=>true');await click('#gwt-debug-manufacturers tbody td:last-child button');await sleep(1500);
ok('mfr deleted',await rows('gwt-debug-manufacturers')===n-1);
await go('rating');n=await rows('gwt-debug-ratings');
await click('#gwt-debug-ratingCreate');await sleep(1000);
await ev(`(()=>{const e=document.querySelector('#gwt-debug-ratingInput');e.value+='10';e.dispatchEvent(new Event('input'))})()`);await click('#gwt-debug-ratingSave');await sleep(1500);
ok('rating success',await ev('!!document.querySelector("#gwt-debug-successMessage")'));
ok('rating added',await rows('gwt-debug-ratings')===n+1);
n=n+1;await ev('window.confirm=()=>true');await click('#gwt-debug-ratings tbody td:last-child button');await sleep(1500);
ok('rating deleted',await rows('gwt-debug-ratings')===n-1);
const avg=await ev(`(()=>{const d={};for(const r of document.querySelector('#gwt-debug-ratings tbody').rows){const m=r.cells[1].textContent.split('/')[0];(d[m]=d[m]||[]).push(+r.cells[2].textContent)}return d})()`);
await go('report');
const rep=await ev(`[...document.querySelector('#gwt-debug-reports tbody').rows].map(r=>[r.cells[0].textContent,+r.cells[1].textContent])`);
ok('report averages',rep.length>0&&rep.every(([m,v])=>avg[m]&&Math.abs(avg[m].reduce((a,b)=>a+b)/avg[m].length-v)<0.001));
ch.kill();process.exit();})();
EOF
