input.command:
cd /work/src/app && python3 - <<'EOF'
p='report.component.ts';s=open(p).read()
s=s.replace("import { API, ManufacturerRatingDto } from './api';","import { API, ManufacturerRatingDto, RatingDto } from './api';")
s=s.replace("error: () => this.msgs.error('An error occurred while loading reports') });","error: () => this.fallback() });
  }
  private fallback() {
    this.http.get<RatingDto[]>(API + '/ratings').subscribe({
      next: rs => {
        const m = new Map<string, number[]>();
        for (const r of rs) { const k = r.car?.manufacturer?.name ?? ''; if (!m.has(k)) m.set(k, []); m.get(k)!.push(r.rating ?? 0); }
        this.list = [...m].map(([manufacturer, v]) => ({ manufacturer, rating: v.reduce((a, b) => a + b, 0) / v.length }));
      },
      error: () => this.msgs.error('An error occurred while loading reports') });")
open(p,'w').write(s)
EOF
